window.__CH("c24",["<div class=\"hw\">pāginula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://pāgina\">pāgina</a>]</div><div class=\"def\">(筆記用紙・書き物の)一区画.</div>\r\n","<div class=\"hw\">pāgus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf. </i> pango]</div><div class=\"def\"><num>①</num> 村, 郷.</div><div class=\"def\"><num>②</num> 村人.</div>\r\n","<div class=\"hw\">pāgānismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://pāgānus\">pāgānus<SUP>1</SUP></a>]</div><div class=\"def\">異教, 偶像崇拝.</div>\r\n","<div class=\"hw\">pāgānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pagus]</div><div class=\"def\"><num>①</num> 村の, 田舎の;田舎者の.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(軍人に対し)一般市民の.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 異教(徒)の.</div><hr><div class=\"hw\">pāgānus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 村人, 田舎の人.</div><div class=\"def\"><num>②</num> (軍人に対し)一般市民, 民間人.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 異教徒.</div>\r\n","<div class=\"hw\">pāgātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[pagus]</div><div class=\"def\">地域[村]ごとに.</div>\r\n","<div class=\"hw\">pāla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf</i>. pango]</div><div class=\"def\"><num>①</num> 鋤<SUB>すき</SUB>.</div><div class=\"def\"><num>②</num> 指輪の台座.</div>\r\n","<div class=\"hw\">pālor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"def\"><num>①</num> (特に, 略奪のために)歩きまわる, うろつく.</div><div class=\"def\"><num>②</num> 散らばる, さまよう.</div>\r\n","<div class=\"hw\">pālus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf</i>. pango, paciscor]</div><div class=\"def\"><num>①</num> 杭, 棒;火刑柱.</div><div class=\"def\"><num>②</num> 木釘.</div>\r\n","<div class=\"hw\">pālāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[palus<SUP>1</SUP>]</div><div class=\"def\">杭の;木刀の.</div>\r\n","<div class=\"hw\">pālātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[palus<SUP>1</SUP>]</div><div class=\"def\">杭を打ち込むこと.</div>\r\n","<div class=\"hw\">pālō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[palus<SUP>1</SUP>]</div><div class=\"def\">(ブドウのつるを)支柱で支える.</div><hr><div class=\"hw\">pālō<SUP>2</SUP></div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[pala]</div><div class=\"def\">(地面を)掘り返す.</div>\r\n","<div class=\"hw\">Pān</div><div class=\"pos\">-nos, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙</div><div class=\"def\"><num>①</num> パーン《森・牧人・家畜などの神;ヤギの角・足をもち, 笛を吹く;ローマ神話の Faunus と同一視される》.</div><div class=\"def\"><num>②</num> (<i>pl</i> Pānes)パーネス《Pan に似た森・野辺の神々》.</div>\r\n","<div class=\"hw\">pānicellus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[panis]</div><div class=\"def\">パンの(小さな)塊り.</div>\r\n","<div class=\"hw\">pānicium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[panis]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 焼いたもの《パン・ケーキなど》.</div><div class=\"def\"><num>②</num> =<a href=\"entry://pānicum\">panicum</a>.</div>\r\n","<div class=\"hw\">pāniculus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[panus]</div><div class=\"def\">〘植〙円錐花序.</div>\r\n","<div class=\"hw\">pānicum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[panus]</div><div class=\"def\">〘植〙アワ(粟).</div>\r\n","<div class=\"hw\">pānifex</div><div class=\"pos\">-ficis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[panis/facio]</div><div class=\"def\">パン製造人.</div>\r\n","<div class=\"hw\">pānificium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://pānis\">pānis</a>/facio]</div><div class=\"def\"><num>①</num> パンを焼くこと.</div><div class=\"def\"><num>②</num> (<i>pl</i>)(焼いた)パン, ケーキ.</div>\r\n","<div class=\"hw\">pānis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>cf. </i> pasco]</div><div class=\"def\"><num>①</num> パン(の塊り).</div><div class=\"def\"><num>②</num> 食物, 生活の糧.</div><div class=\"def\"><num>③</num> 塊り.</div>\r\n","<div class=\"hw\">Pāniscus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"def\"><num>①</num> (小さな)Pan.</div><div class=\"def\"><num>②</num> (小さな)Pan の像.</div>\r\n","<div class=\"hw\">pānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (糸を巻きつけた)糸巻き.</div><div class=\"def\"><num>②</num> 腫<SUB>は</SUB>れ物.</div><div class=\"def\"><num>③</num> 粟の穂.</div>\r\n","<div class=\"hw\">pānāriolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://pānārium\">pānārium</a>]</div><div class=\"def\">(小さな)パンかご.</div>\r\n","<div class=\"hw\">pānārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[panis]</div><div class=\"def\">パンかご.</div>\r\n","<div class=\"hw\">pāpa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘カト〙司教, 大司教;教皇.</div>\r\n","<div class=\"hw\">pāpiliō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\"><num>①</num> 〘昆〙チョウ(蝶);ガ(蛾).</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 天幕, テント.</div>\r\n","<div class=\"hw\">pāpista</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[papa]</div><div class=\"def\">教皇派, カトリック教徒.</div>\r\n","<div class=\"hw\">pāpisticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[papa]</div><div class=\"def\">カトリックの.</div>\r\n","<div class=\"hw\">pāpālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[papa]</div><div class=\"def\">教皇の.</div>\r\n","<div class=\"hw\">pāpās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">家庭教師.</div>\r\n","<div class=\"hw\">pāpātus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[papa]</div><div class=\"def\">〘カト〙教皇の職[位], 教皇権;教皇政治[制度].</div>\r\n","<div class=\"hw\">pār<SUP>1</SUP></div><div class=\"pos\">paris, <i>adj</i></div><div class=\"def\"><num>①</num> 等しい, 同等の;一様な, 均一の 〈+<i>dat</i>;cum alqo;ac, atque〉.</div><div class=\"def\"><num>②</num> 偶数の.</div><div class=\"def\"><num>③</num> 同様の, 類似した.</div><div class=\"def\"><num>④</num> 釣り合った, 相応する</div><div class=\"ex\">～ <i>sapientia ac forma</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">美貌にふさわしい知恵.</span></div><div class=\"def\"><num>⑤</num> (任に)耐えうる;匹敵する 〈+<i>dat</i>;ad alqd〉.</div><div class=\"def\"><num>⑥</num> 対抗[競争]する.</div><div class=\"def\"><num>⑦</num> 互角の</div><div class=\"ex\">～ <i>certamen</i> (<author>C<small>AES</small></author>)<span class=\"ext\">互角の戦い.</span></div><div class=\"def\"><num>⑧</num> 公正な, 正当な, 合理的な.</div><hr><div class=\"hw\">pār<SUP>2</SUP></div><div class=\"pos\">paris, <i>m</i>, <i>f</i></div><div class=\"def\"><num>①</num> 対等の[同等の]者</div><div class=\"ex\"><i>pares cum paribus congregantur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">《諺》類は友を呼ぶ.</span></div><div class=\"def\"><num>②</num> 仲間, 相棒.</div><div class=\"def\"><num>③</num> 競争相手, 敵手.</div><hr><div class=\"hw\">pār<SUP>3</SUP></div><div class=\"pos\">paris, <i>n</i></div><div class=\"ori\">[par<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 一対, 一組.</div><div class=\"def\"><num>②</num> 夫婦.</div><div class=\"def\"><num>③</num> 二人組.</div>\r\n","<div class=\"hw\">pārens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[pareo]</div><div class=\"def\">従順な, 服従する.</div>\r\n","<div class=\"hw\">pārentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[pareo]</div><div class=\"def\">服従.</div>\r\n","<div class=\"hw\">pāreō</div><div class=\"pos\">-ēre pāruī pāritum, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> pario<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 見える, 現われる.</div><div class=\"def\"><num>②</num> (特に <i>impers</i> で)明白である, 明らかである.</div><div class=\"def\"><num>③</num> 服従する;(命令・申し出などに)従う, 応ずる 〈+<i>dat</i>〉.</div><div class=\"def\"><num>④</num> 従属する, 屈服する.</div><div class=\"def\"><num>⑤</num> 供をする 〈alci〉.</div>\r\n","<div class=\"hw\">pāritor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[pareo]</div><div class=\"def\">護衛, 従者.</div>\r\n","<div class=\"hw\">Pāsiphaē</div><div class=\"pos\">-ēs, <B>Pāsiphaa</B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙パーシパエー《Minos の妻で Phaedra, Ariadna の母;白い雄牛と交わって Minotaurus を生んだ》.</div>\r\n","<div class=\"hw\">Pāsiphaēia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">Pasiphae の娘(=<a href=\"entry://Phaedra\">Phaedra</a>).</div>\r\n","<div class=\"hw\">Pāsithea</div><div class=\"pos\">-ae, <B>Pāsitheē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙パーシテア(ー), 《美の三女神 Gratiae の一人》.</div>\r\n","<div class=\"hw\">Pāsitigris</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">パーシティグリス《Tigris 川と Euphrates 川が合流してできた川(現 Shatt al-Arab)に東から注ぐ支流;現 Karun》.</div>\r\n","<div class=\"hw\">pāva</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[pavus]</div><div class=\"def\">〘鳥〙クジャク(孔雀)の雌.</div>\r\n","<div class=\"hw\">pāvus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://pāvō\">pavo</a>.</div>\r\n","<div class=\"hw\">pāvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://pascō\">pasco</a>, <a href=\"entry://paveō\">paveo</a>.</div>\r\n","<div class=\"hw\">pāvō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">〘鳥〙(雄の)クジャク(孔雀).</div>\r\n","<div class=\"hw\">pāvōnāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://pāvō\">pāvō</a>]</div><div class=\"def\">孔雀の尾に似た.</div>\r\n","<div class=\"hw\">pāvōnīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pavo]</div><div class=\"def\"><num>①</num> 孔雀の.</div><div class=\"def\"><num>②</num> 孔雀の羽で作られた.</div><div class=\"def\"><num>③</num> (孔雀の羽のような)玉虫色の.</div>\r\n","<div class=\"hw\">Pēdasa</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ペーダサ《Caria の町》.</div>\r\n","<div class=\"hw\">pēdiculus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[pedis]</div><div class=\"def\">〘昆〙(小さな)シラミ.</div>\r\n","<div class=\"hw\">pēdiculāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[pediculus<SUP>2</SUP>]</div><div class=\"def\">シラミの.</div>\r\n","<div class=\"hw\">pēdicōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pedis]</div><div class=\"def\">シラミだらけの.</div>\r\n","<div class=\"hw\">pēdis</div><div class=\"pos\">-is, <i>m f</i></div><div class=\"def\">〘昆〙シラミ(虱).</div>\r\n","<div class=\"hw\">pēditum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[pedo<SUP>2</SUP>]</div><div class=\"def\">屁, おなら.</div>\r\n","<div class=\"hw\">pēditus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://pēdō\">pedo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">pēdō<SUP>2</SUP></div><div class=\"pos\">-ere pepēdī pēditum, <i>intr</i></div><div class=\"def\">屁をひる.</div>\r\n","<div class=\"hw\">Pēgasides</div><div class=\"pos\">-um, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=Musae.</div>\r\n","<div class=\"hw\">Pēgasis<SUP>1</SUP></div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Pegasus<SUP>1</SUP> の;Hippocrene の.</div><hr><div class=\"hw\">Pēgasis<SUP>2</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ペーガシス《泉のニンフ》.</div>\r\n","<div class=\"hw\">Pēgasus<SUP>1</SUP>, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘神話〙ペーガスス, <SUP>*</SUP>-ソス《Perseus に殺された Medusa の血から生まれ出た翼のある天馬;その一蹴りで Hippocrene の泉ができた》.</div><div class=\"def\"><num>②</num> 〘天〙ペガスス座.</div><hr><div class=\"hw\">Pēgasus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ペーガスス《Vespasianus 帝時代の著名な法学者》.</div>\r\n","<div class=\"hw\">Pēgasēius, -seus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Pegasus<SUP>1</SUP> の.</div>\r\n","<div class=\"hw\">Pēgē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ペーゲー《Bithynia の泉》.</div>\r\n","<div class=\"hw\">pēgī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://pangō\">pango</a>.</div>\r\n","<div class=\"hw\">pējerātiuncula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://pējerātiō\">pējerātiō</a>]</div><div class=\"def\">(軽微な)偽証.</div>\r\n","<div class=\"hw\">pējerātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[pejero]</div><div class=\"def\">偽誓, 偽証.</div>\r\n","<div class=\"hw\">pējerō, perjerō, perjūrō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[per-/juro]</div><div class=\"def\">偽誓[偽証]する</div><div class=\"ex\"><i>jus pejeratum</i> (<author>H<small>OR</small></author>)<span class=\"ext\">偽誓.</span></div>\r\n","<div class=\"hw\">pējor</div><div class=\"pos\">-or -us, <i>adj comp</i>(原級 malus)</div><div class=\"def\">より悪い;より有害な;より劣る, より下位の.</div>\r\n","<div class=\"hw\">pējōrō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i>, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[↑<a href=\"entry://pējor\">pējor</a>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)悪くする, 悪化させる.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)悪くなる, 悪化する.</div>\r\n","<div class=\"hw\">pējūr-</div><div class=\"def\">⇒perjur-.</div>\r\n","<div class=\"hw\">pēlamys</div><div class=\"pos\">-ydis, <B>-is</B> -idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙マグロの稚魚.</div>\r\n","<div class=\"hw\">Pēleus</div><div class=\"pos\">-eos [-eī], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ペーレウス《Aeacus の子で Achilles の父》.</div>\r\n","<div class=\"hw\">pēlex</div><div class=\"pos\">-licis, <i>f</i></div><div class=\"def\">=<a href=\"entry://paelex\">paelex</a>.</div>\r\n","<div class=\"hw\">Pēliacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Pelion 山の.</div>\r\n","<div class=\"hw\">Pēlias<SUP>2</SUP></div><div class=\"pos\">-adis, <i>adj f</i></div><div class=\"def\">Pelion 山の.</div>\r\n","<div class=\"hw\">pēlicātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">=<a href=\"entry://paelicātus\">paelicatus</a>.</div>\r\n","<div class=\"hw\">Pēlign-</div><div class=\"def\">⇒Paelign-.</div>\r\n","<div class=\"hw\">Pēlion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ペーリオン《Thessalia 東部の山》.</div>\r\n","<div class=\"hw\">Pēlius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Pelion 山の.</div>\r\n","<div class=\"hw\">Pēlēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Peleus の;Achilles の.</div>\r\n","<div class=\"hw\">Pēlīdēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\"><num>①</num> Peleus の息子(=<a href=\"entry://Achillēs\">Achilles</a>).</div><div class=\"def\"><num>②</num> Peleus の孫(=<a href=\"entry://Neoptolemus\">Neoptolemus</a>).</div>\r\n","<div class=\"hw\">Pēlūsiacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Pelusium の.</div>\r\n","<div class=\"hw\">Pēlūsium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ペルーシウム, <SUP>*</SUP>-オン《Nilus 川の東側の河口の町》.</div>\r\n","<div class=\"hw\">Pēlūsius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Pēlūsiacus\">Pelusiacus</a>.</div>\r\n","<div class=\"hw\">Pēlūsiōtēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Pelusium の住民.</div>\r\n","<div class=\"hw\">Pēneleus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ペーネレウス, <SUP>*</SUP>-レオース《Helena の求婚者の一人》.</div>\r\n","<div class=\"hw\">Pēnelopē</div><div class=\"pos\">-ēs, <B>-a</B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ペーネロペー《Icarius の娘;Ulixes の妻で Telemachus の母;夫の20年間の不在中貞節を守り続けた》.</div>\r\n","<div class=\"hw\">Pēnelopēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Penelope の.</div>\r\n","<div class=\"hw\">pēnicillinum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://pēnicillium\">pēnicillium</a>]</div><div class=\"def\">〘薬〙ペニシリン.</div>\r\n","<div class=\"hw\">pēnicillium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://pēnicillus\">pēnicillus</a>]</div><div class=\"def\">〘植〙ペニシリウム属, アオカビ類.</div>\r\n","<div class=\"hw\">pēnicillus</div><div class=\"pos\">-ī, <i>m</i>, <B>-um</B> -ī, <i>n dim</i></div><div class=\"ori\">[penis]</div><div class=\"def\"><num>①</num> 絵筆.</div><div class=\"def\"><num>②</num> 絵画.</div><div class=\"def\"><num>③</num> 文体, 筆致.</div><div class=\"def\"><num>④</num> 海綿.</div><div class=\"def\"><num>⑤</num> (傷口に当てる)布.</div>\r\n","<div class=\"hw\">pēnicillī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[penicillus]</div><div class=\"def\">〘解〙筆毛動脈.</div>\r\n","<div class=\"hw\">pēniculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://pēnis\">pēnis</a>]</div><div class=\"def\"><num>①</num> はけ.</div><div class=\"def\"><num>②</num> 海綿.</div>\r\n","<div class=\"hw\">pēnis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> (動物の)尾, しっぽ.</div><div class=\"def\"><num>②</num> 男根, 陰茎.</div>\r\n","<div class=\"hw\">pēnul-</div><div class=\"def\">⇒paenul-.</div>\r\n","<div class=\"hw\">Pēnēis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Peneus の.</div>\r\n","<div class=\"hw\">Pēnēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Peneus の.</div>\r\n","<div class=\"hw\">Pēnēus<SUP>1</SUP>, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ペーネーウス, <SUP>*</SUP>-ネイオス《 (1) Thessalia の川;Tempe 峡谷を通って海に注ぐ.(2) 〘神話〙(1) の河神;Cyrene と Daphne の父》.</div><hr><div class=\"hw\">Pēnēus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Pēnēius\">Peneius</a>.</div>\r\n","<div class=\"hw\">pēnītus<SUP>3</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[penis]</div><div class=\"def\">しっぽの付いた.</div>\r\n","<div class=\"hw\">pēnūria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">欠乏, 不足;窮乏 〈+<i>gen</i>〉.</div>\r\n","<div class=\"hw\">pēra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">合切袋, 背嚢.</div>\r\n","<div class=\"hw\">pērula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[pera]</div><div class=\"def\">(小さな)袋.</div>\r\n","<div class=\"hw\">pērātus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[pera]</div><div class=\"def\">合切袋を肩にしている男.</div>\r\n","<div class=\"hw\">pērō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">生皮の長靴.</div>\r\n","<div class=\"hw\">Pērō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ペーロー《Neleus の娘で Nestor の姉妹》.</div>\r\n","<div class=\"hw\">pēs</div><div class=\"pos\">pedis, <i>m</i></div><div class=\"def\"><num>①</num> 足</div><div class=\"ex\"><i>nec caput nec ～ sermoni apparet</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">その話は頭も足も(=何が何だかさっぱり)わからない</span></div><div class=\"ex\"><i>pedem ferre</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">足を運ぶ, 行く</span></div><div class=\"ex\"><i>pedem referre</i> (<author>O<small>V</small></author>)<span class=\"ext\">退く</span></div><div class=\"ex\"><i>pedem conferre</i> (<author>L<small>IV</small></author>)<span class=\"ext\">接近戦をする</span></div><div class=\"ex\"><i>pedibus</i> (<author>C<small>AES</small></author>)<span class=\"ext\">徒歩で;陸路で</span></div><div class=\"ex\"><i>ante pedes</i> (<author>C<small>IC</small></author>)<span class=\"ext\">足の前に(=目の前に;明らかで).</span></div><div class=\"def\"><num>②</num> (卓・椅子などの)脚;(ものの)最下部.</div><div class=\"def\"><num>③</num> 〘海〙帆脚索<SUB>ほあしづな</SUB>.</div><div class=\"def\"><num>④</num> 果実をつけた柄<SUB>え</SUB>.</div><div class=\"def\"><num>⑤</num> 地所, 敷地;領地.</div><div class=\"def\"><num>⑥</num> 長さの単位(=約29.6<i>cm</i>).</div><div class=\"def\"><num>⑦</num> 〘詩〙詩脚;韻律.</div><div class=\"def\"><num>⑧</num> 〘音〙拍子.</div>\r\n","<div class=\"hw\">Pētitarus</div><div class=\"pos\">-ī</div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ペーティタルス, <SUP>*</SUP>-ロス《Aetolia の 川》.</div>\r\n","<div class=\"hw\">pīca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘鳥〙カケス, カササギ.</div>\r\n","<div class=\"hw\">Pīcens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"def\">Picenum の.</div><div class=\"hw2\"><b>Pīcentēs</b></div><div class=\"pos2\">-ium [-um], <i>m pl</i></div><div class=\"def2\">Picenum の住民.</div>\r\n","<div class=\"hw\">Pīcentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ピーケンティア《Campania 南部の町》.</div>\r\n","<div class=\"hw\">Pīcentiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《碑》Picenum の.</div>\r\n","<div class=\"hw\">Pīcentīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Picentia の.</div><div class=\"def\"><num>②</num> Picenum の.</div>\r\n","<div class=\"hw\">Pīcumnus</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘神話〙ピークムヌス《夫婦と子どもの守護神;Pilumnus とともに崇拝された》.</div>\r\n","<div class=\"hw\">pīcus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘鳥〙[<i>cf</i>. pica]キツツキ(啄木鳥).</div>\r\n","<div class=\"hw\">Pīcus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ピークス《Saturnus の息子;Latinus の祖父;Circe によってキツツキに変えられた》.</div>\r\n","<div class=\"hw\">pīcātus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pix<SUP>2</SUP>]</div><div class=\"def\">スフィンクスに似た.</div>\r\n","<div class=\"hw\">Pīcēnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ピーケーヌム《イタリア中東部のアドリア海に面する地域》.</div>\r\n","<div class=\"hw\">Pīcēnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Pīcens\">Picens</a>.</div>\r\n","<div class=\"hw\">Pīeria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピーエリア(ー)《 (1) Macedonia の Olympus 山の北麓地方;Musae の生地と伝えられる.(2) Syria の一地域;Cilicia と Phoenicia の間に位置した》.</div>\r\n","<div class=\"hw\">Pīeriae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">Musae の呼称の一つ.</div>\r\n","<div class=\"hw\">Pīeris</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Pieros の娘の一人(=<a href=\"entry://Mūsa\">Musa</a>).</div>\r\n","<div class=\"hw\">Pīerius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Musae の;詩の.</div><div class=\"def\"><num>②</num> Pieria (1) の;Macedonia の;Thessalia の.</div>\r\n","<div class=\"hw\">Pīeros, -us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ピーエロス《Macedonia の Pella の王;彼の9人の娘が Musae と競ってカササギに変えられた;一説に Musae の父》.</div>\r\n","<div class=\"hw\">pīla<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf</i>. pinso]</div><div class=\"def\">臼<SUB>うす</SUB>, すり鉢.</div><hr><div class=\"hw\">pīla<SUP>2</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">柱.</div>\r\n","<div class=\"hw\">pīlentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">(貴婦人用の)四輪馬車.</div>\r\n","<div class=\"hw\">Pīlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ピーリア《Atticus の妻》.</div>\r\n","<div class=\"hw\">pīlum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> すりこぎ, きね.</div><div class=\"def\"><num>②</num> 投げ槍.</div>\r\n","<div class=\"hw\">Pīlumnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ピールムヌス《 (1) 〘神話〙夫婦と子どもの守護神;Picumnus とともに崇拝された.(2) 〘伝説〙Turnus の會祖父》.</div>\r\n","<div class=\"hw\">pīlus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[pilum]</div><div class=\"def\">(ローマ軍の)第三戦列(triarii)の一部</div><div class=\"ex\"><i>primum pilum ducere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">(百人隊長が)軍団の第1大隊(cohors)第1百人隊(centuria)を指揮する</span></div><div class=\"ex\"><i>centurio primi pili</i> (<author>C<small>AES</small></author>)<span class=\"ext\">(軍団の)首位百人隊長(=<a href=\"entry://prīmipīlus\">primipilus</a>).</span></div>\r\n","<div class=\"hw\">pīlānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[pilum]</div><div class=\"def\">第三戦列兵(<i>cf</i>. triarii).</div>\r\n","<div class=\"hw\">pīlārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[pila<SUP>2</SUP>]</div><div class=\"def\">《碑》納骨堂.</div>\r\n","<div class=\"hw\">pīlātim<SUP>1</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[pila<SUP>2</SUP>]</div><div class=\"def\">柱によって.</div><hr><div class=\"hw\">pīlātim<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[pilatus<SUP>1</SUP>]</div><div class=\"def\">密集隊形をなして.</div>\r\n","<div class=\"hw\">pīlātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pila<SUP>2</SUP>]</div><div class=\"def\">密集隊形の.</div><hr><div class=\"hw\">pīlātus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pilum]</div><div class=\"def\">投げ槍で武装した.</div>\r\n","<div class=\"hw\">Pīlātus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ピーラートゥス《ローマ人の家名;特に <i>Pontius ～</i>, Judaea 総督(26‐36);キリストの処刑を許可したと伝えられる》.</div>\r\n","<div class=\"hw\">pīlō<SUP>1</SUP></div><div class=\"pos\">-āre -ātum, <i>tr</i></div><div class=\"ori\">[pila<SUP>2</SUP>]</div><div class=\"def\">しっかり固定する.</div>\r\n","<div class=\"hw\">pīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙二枚貝《タイラギの類》.</div>\r\n","<div class=\"hw\">pīnea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[pineus]</div><div class=\"def\">〘植〙松の実.</div>\r\n","<div class=\"hw\">pīneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pinus]</div><div class=\"def\">松の木の;松材の.</div>\r\n","<div class=\"hw\">pīneālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙松果体の.</div>\r\n","<div class=\"hw\">pīnifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[pinus/fero]</div><div class=\"def\">松の生える.</div>\r\n","<div class=\"hw\">pīniger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[pinus/gero]</div><div class=\"def\">松(の木)におおわれた.</div>\r\n","<div class=\"hw\">pīnotērēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙カクレガニ.</div>\r\n","<div class=\"hw\">pīnus</div><div class=\"pos\">-ūs [-ī], <i>f</i></div><div class=\"def\"><num>①</num> 〘植〙松の木.</div><div class=\"def\"><num>②</num> 松葉飾り.</div><div class=\"def\"><num>③</num> 船;帆柱.</div><div class=\"def\"><num>④</num> かい, オール.</div><div class=\"def\"><num>⑤</num> たいまつ.</div>\r\n","<div class=\"hw\">pīnālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[pinus]</div><div class=\"def\">松の.</div>\r\n","<div class=\"hw\">Pīnārius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ピーナーリウス《ローマの貴族階級に属する氏族名;特に Hercules の祭祀にたずさわった》.</div><hr><div class=\"hw\">Pīnārius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Pinarius の.</div>\r\n","<div class=\"hw\">pīnētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[pinus]</div><div class=\"def\">松林.</div>\r\n","<div class=\"hw\">pīpilō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\">(スズメが)ピーピー鳴く, さえずる.</div>\r\n","<div class=\"hw\">pīpiō<SUP>1</SUP></div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\"><num>①</num> (スズメが)ピーピー鳴く.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(小児が)めそめそ泣く.</div><hr><div class=\"hw\">pīpiō<SUP>2</SUP></div><div class=\"pos\">-īre, <i>intr</i></div><div class=\"def\">(ひよこが)ピーピー鳴く.</div><hr><div class=\"hw\">pīpiō<SUP>3</SUP></div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">ひな鳥.</div>\r\n","<div class=\"hw\">pīpulum</div><div class=\"pos\">-ī, <i>n</i>, <B>-us</B> -ī, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://pīpō\">pīpō</a>]</div><div class=\"def\">叫び[わめき]声.</div>\r\n","<div class=\"hw\">pīpō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">(メンドリが)鳴く.</div>\r\n","<div class=\"hw\">Pīraeus<SUP>1</SUP></div><div class=\"pos\">-ī, <B>Pīraeeus</B> -eī [-eos], <i>m</i>, <B>Pīraea</B> -ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピーラエウス, <SUP>*</SUP>ペイライエウス《Athenae の外港》.</div><hr><div class=\"hw\">Pīraeus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Piraeus 港の.</div>\r\n","<div class=\"hw\">Pīrithous</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピーリトウス, <SUP>*</SUP>ペイリトオス《Lapithae 族の王;親友 Theseus とともに黄泉の国から Proserpina を連れ出そうとして果たさなかった》.</div>\r\n","<div class=\"hw\">pīrāta</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">海賊.</div>\r\n","<div class=\"hw\">pīrātica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[piraticus]</div><div class=\"def\">海賊行為.</div>\r\n","<div class=\"hw\">pīrāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">海賊の.</div>\r\n","<div class=\"hw\">pīrāticē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://pīrāticus\">pīrāticus</a>]</div><div class=\"def\">海賊のように[として].</div>\r\n","<div class=\"hw\">pīrātērium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\"><num>①</num> 略奪者の群れ.</div><div class=\"def\"><num>②</num> 試練.</div>\r\n","<div class=\"hw\">Pīrēnis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Pirene の.</div>\r\n","<div class=\"hw\">Pīrēnē</div><div class=\"pos\">-ēs, <B>-a</B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピーレーネー, <SUP>*</SUP>ペイ-《Corinthus の泉;天馬 Pegasus のひづめの一蹴りで涌いたという;Musae の聖泉》.</div>\r\n","<div class=\"hw\">Pīrūstae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピールースタエ, <SUP>*</SUP>ペイルースタイ《Illyria にいた一部族》.</div>\r\n","<div class=\"hw\">pīsa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://pīsum\">pisum</a>.</div>\r\n","<div class=\"hw\">Pīsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピーサ《Elis の Alpheus 河畔の町;この近くの野で Olympia 競技祭が催された》.</div>\r\n","<div class=\"hw\">Pīsae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ピーサエ《Etruria の町;Pisa の植民市といわれる;現 Pisa》.</div>\r\n","<div class=\"hw\">Pīsaea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://Pīsaeus\">Pīsaeus</a>]</div><div class=\"def\">Pisa の女(=<a href=\"entry://Hippodamīa\">Hippodamia</a>).</div>\r\n","<div class=\"hw\">Pīsaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Pisa の.</div>\r\n","<div class=\"hw\">Pīsander</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピーサンデル, <SUP>*</SUP>ペイサンドロス《 (1) 〘伝説〙Penelope の求婚者の一人.(2) Rhodos 島の Camirus 生まれのギリシアの叙事詩人(前7‐6世紀頃).(3) Athenae の政治家(前5世紀)》.</div>\r\n","<div class=\"hw\">pīsiformis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[pisum/forma]</div><div class=\"def\">〘解〙豆状の.</div>\r\n","<div class=\"hw\">Pīsistratidae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Pisistratus の息子たち(=<a href=\"entry://Hippiās\">Hippias</a> と <a href=\"entry://Hipparchus\">Hipparchus</a>).</div>\r\n","<div class=\"hw\">Pīsistratus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピーシストラトゥス, <SUP>*</SUP>ペイシストラトス《Athenae の僭主(前605?‐527)》.</div>\r\n","<div class=\"hw\">pīsum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙エンドウ(豆).</div>\r\n","<div class=\"hw\">Pīsānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Pisae の.</div>\r\n","<div class=\"hw\">pīsātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[piso]</div><div class=\"def\">踏みつけること.</div>\r\n","<div class=\"hw\">pīsō<SUP>1, 2</SUP></div><div class=\"def\">=<a href=\"entry://pinsō\">pinso<SUP>1</SUP></a>, <a href=\"entry://pinsō\">pinso<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Pīsō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">ピーソー《Calpurnia 氏族に属する家名;特に (1) <i>L. Calpurnius ～ Caesoninus</i>, 執政官(前58).(2) <i>L. Calpurnius ～ Frugi</i>, 執政官(前15).(3) <i>Cn. Calpurnius ～</i>, 執政官(前7);後19年に Germanicus 殺害の容疑で告発された.(4) <i>C. Calpurnius ～</i>, 後65年の Nero 帝に対する陰謀の首謀者とされる》.</div>\r\n","<div class=\"hw\">Pīsōniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Piso の.</div>\r\n","<div class=\"hw\">Pītholeō(n)</div><div class=\"pos\">-ontis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ピートレオー, <SUP>*</SUP>ペイトレオーン《Rhodos 島生まれのへぼ詩人(前50頃)》.</div>\r\n","<div class=\"hw\">pītuīta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 粘膜の分泌物.</div><div class=\"def\"><num>②</num> (家禽の)舌病.</div><div class=\"def\"><num>③</num> 膿汁.</div><div class=\"def\"><num>④</num> 粘着性の樹液.</div>\r\n","<div class=\"hw\">pītuītōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://pītuīta\">pītuīta</a>]</div><div class=\"def\">カタルにかかった, 粘液過多の.</div>\r\n","<div class=\"hw\">pōcillum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[poculum]</div><div class=\"def\">(小さな)杯;小カップ一杯(の量).</div>\r\n","<div class=\"hw\">pōculentus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://pōculum\">pōculum</a>]</div><div class=\"def\">飲用に適した.</div>\r\n","<div class=\"hw\">pōculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 杯.</div><div class=\"def\"><num>②</num> 飲み物;酒</div><div class=\"ex\"><i>amoris</i> ～ (<author>H<small>OR</small></author>)<span class=\"ext\">媚薬.</span></div><div class=\"def\"><num>③</num> 毒盃.</div><div class=\"def\"><num>④</num> (<i>pl</i>)宴会.</div><div class=\"def\"><num>⑤</num> 飲むこと</div><div class=\"ex\"><i>ad pocula venire</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">(水を)飲みに来る.</span></div>\r\n","<div class=\"hw\">pōdex</div><div class=\"pos\">-dicis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> pedo<SUP>2</SUP>]</div><div class=\"def\">肛門.</div>\r\n","<div class=\"hw\">pōlēa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ロバの子の糞.</div>\r\n","<div class=\"hw\">pōlīa<SUP>2</SUP></div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">馬の飼育場.</div>\r\n","<div class=\"hw\">pōlūbrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[polluo]</div><div class=\"def\">洗盤, 手洗い鉢.</div>\r\n","<div class=\"hw\">pōmerīdiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">⇒<a href=\"entry://postmerīdiānus\">postmeridianus</a>.</div>\r\n","<div class=\"hw\">pōmifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[pomum/fero]</div><div class=\"def\">果実を生ずる, 実を結ばせる.</div>\r\n","<div class=\"hw\">pōmoerium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://pōmērium\">pomerium</a>.</div>\r\n","<div class=\"hw\">pōmum</div><div class=\"pos\">-ī, <i>n</i>, <B>-us</B> -ī, <i>f</i></div><div class=\"def\"><num>①</num> 果物, 果実.</div><div class=\"def\"><num>②</num> 果樹.</div>\r\n","<div class=\"hw\">pōmusculum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↑<a href=\"entry://pōmum\">pōmum</a>]</div><div class=\"def\">(小さな)果実.</div>\r\n","<div class=\"hw\">pōmārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://pōmārius\">pōmārius<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 果樹園.</div><div class=\"def\"><num>②</num> 果物貯蔵所.</div>\r\n","<div class=\"hw\">pōmārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pomum]</div><div class=\"def\">果物の.</div><hr><div class=\"hw\">pōmārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">果物売り;果樹栽培者.</div>\r\n","<div class=\"hw\">pōmērium, pōmoer-</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[post-/moerus(=<a href=\"entry://mūrus\">murus</a>)]</div><div class=\"def\"><num>①</num> 市壁沿いの神聖な土地《建築・居住が許されなかった》.</div><div class=\"def\"><num>②</num> 町の境界.</div><div class=\"def\"><num>③</num> (主題の)限界, 制限.</div>\r\n","<div class=\"hw\">Pōmētia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ポーメーティア《Latium にあった Volsci 族の町;Suessa とも呼ばれた》.</div>\r\n","<div class=\"hw\">Pōmētiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Pometia の住民.</div>\r\n","<div class=\"hw\">pōmētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[pomum]</div><div class=\"def\">果樹園.</div>\r\n","<div class=\"hw\">Pōmētīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Pometia の.</div>\r\n","<div class=\"hw\">Pōmōna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[pomum]</div><div class=\"def\">〘神話〙ポーモーナ《果物と果樹の女神》.</div>\r\n","<div class=\"hw\">Pōmōnal</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"def\">Pomona の神殿.</div>\r\n","<div class=\"hw\">Pōmōnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Pomona の.</div>\r\n","<div class=\"hw\">pōmōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pomum]</div><div class=\"def\"><num>①</num> 果実がよく実った.</div><div class=\"def\"><num>②</num> 果実から成る.</div>\r\n","<div class=\"hw\">pōne</div><div class=\"pos\"><i>adv</i>, <i>prep</i></div><div class=\"ori\">[post]</div><div class=\"def\"><num>①</num> 後ろで;後ろから;後ろへ.</div><div class=\"def\"><num>②</num> ...の後ろで[へ] 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw\">pōnō</div><div class=\"pos\">-ere posuī positum [postum], <i>tr</i></div><div class=\"def\"><num>①</num> 置く, 据える.</div><div class=\"def\"><num>②</num> (陣地を)設営する;(軍勢・兵力を)配置[配備]する.</div><div class=\"def\"><num>③</num> 建てる, 建設する.</div><div class=\"def\"><num>④</num> 植える.</div><div class=\"def\"><num>⑤</num> 差し出す;(飲食物などを)供する.</div><div class=\"def\"><num>⑥</num> (武器を)捨てる, 投ずる.</div><div class=\"def\"><num>⑦</num> (衣類などを)脱ぐ.</div><div class=\"def\"><num>⑧</num> (体の一部を)下に置く</div><div class=\"ex\"><i>pedem ponere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">歩を運ぶ</span></div><div class=\"ex\"><i>genu ponere</i> (<author>O<small>V</small></author>)<span class=\"ext\">ひざまずく.</span></div><div class=\"def\"><num>⑨</num> 取っておく, 貯える</div><div class=\"ex\"><i>tabulas testamenti in aerario ponere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">遺言書の写しを国庫に保管する.</span></div><div class=\"def\"><num>⑩</num> 埋葬する;お供えをする.</div><div class=\"def\"><num>⑪</num> (海を)静める;(<i>pass</i>, <i>intr</i>)(風が)静まる.</div><div class=\"def\"><num>⑫</num> やめる, 廃する, 終わらせる.</div><div class=\"def\"><num>⑬</num> (ある状態に)置く;任命する.</div><div class=\"def\"><num>⑭</num> (時間・労力・金銭などを)費やす;投資する.</div><div class=\"def\"><num>⑮</num> (問題を)課す.</div><div class=\"def\"><num>⑯</num> 名づける.</div><div class=\"def\"><num>⑰</num> 確立する, 定める, 立てる.</div><div class=\"def\"><num>⑱</num> みなす;評価する;数え入れる</div><div class=\"ex\"><i>mortem in malis ponere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">死を禍いの一つに数える.</span></div><div class=\"def\"><num>⑲</num> (...に)基づかせる;(望みを...に)かける</div><div class=\"ex\"><i>omnem spem salutis in virtute ponere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">救出のすべての望みを武勇にかける.</span></div><div class=\"def\"><num>⑳</num> 銘記[明示]する</div><div class=\"ex\"><i>exemplum ponere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">例に引く.</span></div><div class=\"def\"><num>㉑</num> 主張する, 申し立てる.</div><div class=\"def\"><num>㉒</num> 描く, 表現する.</div>\r\n","<div class=\"hw\">pōpuleus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[populus<SUP>2</SUP>]</div><div class=\"def\">ポプラの.</div>\r\n","<div class=\"hw\">pōpulifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[populus<SUP>2</SUP>/fero]</div><div class=\"def\">ポプラの木の多い.</div>\r\n","<div class=\"hw\">pōpulneus, -nus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[populus<SUP>2</SUP>]</div><div class=\"def\">ポプラの.</div>\r\n","<div class=\"hw\">pōpulus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">〘植〙ポプラ.</div>\r\n","<div class=\"hw\">pōpulētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[populus<SUP>2</SUP>]</div><div class=\"def\">ポプラの樹林.</div>\r\n","<div class=\"hw\">pōrus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘地〙石灰華.</div>\r\n","<div class=\"hw\">Pōrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ポールス, <SUP>*</SUP>-ロス《インドの王;Alexander 大王に征服された》.</div>\r\n","<div class=\"hw\">pōsea, pōsia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://pausea\">pausea</a>.</div>\r\n","<div class=\"hw\">pōtilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[poto]</div><div class=\"def\">飲用の.</div>\r\n","<div class=\"hw\">pōtitō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"ori\">[poto]</div><div class=\"def\">たびたび[常に]飲む.</div>\r\n","<div class=\"hw\">pōtiuncula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[potio<SUP>1</SUP>]</div><div class=\"def\">(少しの)飲酒.</div>\r\n","<div class=\"hw\">pōtiō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[poto]</div><div class=\"def\"><num>①</num> 飲むこと;飲酒.</div><div class=\"def\"><num>②</num> 飲み物.</div><div class=\"def\"><num>③</num> 薬の一服;毒薬;媚薬.</div>\r\n","<div class=\"hw\">pōtiōnātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[potio<SUP>1</SUP>]</div><div class=\"def\">薬を飲まされた.</div>\r\n","<div class=\"hw\">pōtor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://pōtō\">pōtō</a>]</div><div class=\"def\"><num>①</num> (水を)飲む人</div><div class=\"ex\"><i>Rhodani ～</i> (<author>H<small>OR</small></author>)<span class=\"ext\">Rhodanus 川の水を飲む者(=川辺の住民).</span></div><div class=\"def\"><num>②</num> 酒飲み, のんだくれ.</div>\r\n","<div class=\"hw\">pōtrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[potor]</div><div class=\"def\">酒豪《女性》.</div>\r\n","<div class=\"hw\">pōtulentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://pōtulentus\">pōtulentus</a>]</div><div class=\"def\">飲み物.</div>\r\n","<div class=\"hw\">pōtulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://pōtus\">pōtus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 飲用に適した.</div><div class=\"def\"><num>②</num> ほろ酔いの, 千鳥足の.</div>\r\n","<div class=\"hw\">pōtus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[poto]</div><div class=\"def\"><num>①</num> 酒を飲んだ;酩酊した.</div><div class=\"def\"><num>②</num> 飲まれた, 飲みほされた.</div><hr><div class=\"hw\">pōtus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 飲むこと.</div><div class=\"def\"><num>②</num> 飲酒;酩酊.</div><div class=\"def\"><num>③</num> 飲み物, 飲料.</div>\r\n","<div class=\"hw\">pōtābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[poto]</div><div class=\"def\">飲める, 飲用に適した.</div>\r\n","<div class=\"hw\">pōtāculum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">=<a href=\"entry://pōtātiō\">potatio</a>.</div>\r\n","<div class=\"hw\">pōtāmentum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[poto]</div><div class=\"def\">飲み物.</div>\r\n","<div class=\"hw\">pōtātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[poto]</div><div class=\"def\">飲酒;酒宴.</div>\r\n","<div class=\"hw\">pōtātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[poto]</div><div class=\"def\">酒飲み.</div>\r\n","<div class=\"hw\">pōtātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://pōtō\">poto</a>.</div><hr><div class=\"hw\">pōtātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">飲酒;酒宴.</div>\r\n","<div class=\"hw\">Pōtīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ポーティーナ《乳離れした幼児の最初の飲み物をつかさどる女神》.</div>\r\n","<div class=\"hw\">pōtō</div><div class=\"pos\">-āre -āvī -ātum [-tum], <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> (渇きをいやすために水を)飲む.</div><div class=\"def\"><num>②</num> (酒を)飲む, 痛飲する.</div><div class=\"def\"><num>③</num> 吸い込む, 吸収する.</div>\r\n","<div class=\"hw\">pōtōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://pōtōrius\">pōtōrius</a>]</div><div class=\"def\">酒杯, さかずき.</div>\r\n","<div class=\"hw\">pōtōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[potor]</div><div class=\"def\">飲むための.</div>\r\n","<div class=\"hw\">pūbens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[pubes]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 思春期に達した.</div><div class=\"def\"><num>②</num> (葉が)みずみずしい, (花が)盛りの.</div>\r\n","<div class=\"hw\">pūber</div><div class=\"pos\">-eris, <i>adj</i></div><div class=\"def\">=<a href=\"entry://pūbēs\">pubes<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">pūbertās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://pūbēs\">pūbēs<SUP>1</SUP>, pūber</a>]</div><div class=\"def\"><num>①</num> 思春期;成年.</div><div class=\"def\"><num>②</num> 思春期の徴候.</div><div class=\"def\"><num>③</num> (植物・果実の)成熟.</div>\r\n","<div class=\"hw\">pūberēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[pubes<SUP>1</SUP>]</div><div class=\"def\">成人した男たち.</div>\r\n","<div class=\"hw\">pūbescō</div><div class=\"pos\">-ere, pūbuī, <i>intr inch</i></div><div class=\"ori\">[pubes<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 思春期に達する, 成人する;恥毛が生える.</div><div class=\"def\"><num>②</num> (植物・果実が)成長する, 成熟する.</div>\r\n","<div class=\"hw\">pūblica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[publicus<SUP>1</SUP>]</div><div class=\"def\">売春婦.</div>\r\n","<div class=\"hw\">pūblicitus</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[publicus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 公的に.</div><div class=\"def\"><num>②</num> 公費で.</div><div class=\"def\"><num>③</num> 公然と.</div>\r\n","<div class=\"hw\">Pūblicius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">プーブリキウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Pūblicola</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">プーブリコラ《ローマ人の家名;特に <i>P. Valerius</i> ～, 最初の執政官の一人とされる》.</div>\r\n","<div class=\"hw\">pūblicum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://pūblicus\">pūblicus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 公有財産, 公有地.</div><div class=\"def\"><num>②</num> 国庫, (国家の)歳入.</div><div class=\"def\"><num>③</num> 公益, 国益.</div><div class=\"def\"><num>④</num> 国家, 共同体.</div><div class=\"def\"><num>⑤</num> 公文書館.</div><div class=\"def\"><num>⑥</num> 公共の場</div><div class=\"ex\"><i>carere publico</i> (<author>C<small>IC</small></author>)<span class=\"ext\">公衆の前に姿を現わさない.</span></div>\r\n","<div class=\"hw\">pūblicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 国民(全体)の, 国家の</div><div class=\"ex\"><i>res publica</i><span class=\"ext\">=<a href=\"entry://rēs pūblica\">respublica</a>.</span></div><div class=\"def\"><num>②</num> 公的な, 公式の.</div><div class=\"def\"><num>③</num> 公共の.</div><div class=\"def\"><num>④</num> 万人共通の</div><div class=\"ex\"><i>lux publica mundi</i> (<author>O<small>V</small></author>)<span class=\"ext\">世界をあまねく照らす光(=太陽).</span></div><div class=\"def\"><num>⑤</num> 《詩》平凡な, 月並みな.</div><hr><div class=\"hw\">pūblicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《碑》国家奴隷.</div>\r\n","<div class=\"hw\">pūblicānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[publicus<SUP>1</SUP>]</div><div class=\"def\">収税請負人の.</div><hr><div class=\"hw\">pūblicānus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">収税請負人.</div>\r\n","<div class=\"hw\">pūblicātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[publico]</div><div class=\"def\"><num>①</num> 没収.</div><div class=\"def\"><num>②</num> 公表.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(法律の)公布.</div>\r\n","<div class=\"hw\">pūblicātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[publico]</div><div class=\"def\">暴露する人.</div>\r\n","<div class=\"hw\">pūblicātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://pūblicātor\">pūblicātor</a>]</div><div class=\"def\">暴露する人《女性》.</div>\r\n","<div class=\"hw\">pūblicē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[publicus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 国家のために, 公けに.</div><div class=\"def\"><num>②</num> 公費で.</div><div class=\"def\"><num>③</num> 公然と.</div><div class=\"def\"><num>④</num> 全体として, 例外なく.</div>\r\n","<div class=\"hw\">pūblicō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[publicus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 公用に供する.</div><div class=\"def\"><num>②</num> 没収する.</div><div class=\"def\"><num>③</num> (身を)売る.</div><div class=\"def\"><num>④</num> 公表する;出版する.</div>\r\n","<div class=\"hw\">Pūblilius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">プーブリリウス《ローマ人の氏族名;特に ～ <i>Syrus</i>, 前1世紀の mimus の作者;彼の名を冠した 「格言集」 が現存する》.</div>\r\n","<div class=\"hw\">Pūblius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">プーブリウス《ローマ人の個人名(略形 P.)》.</div>\r\n","<div class=\"hw\">pūbocapsulāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙恥骨股関節包の.</div>\r\n","<div class=\"hw\">pūboprostaticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙恥骨前立腺の.</div>\r\n","<div class=\"hw\">pūbovēsīcālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙恥骨膀胱の.</div>\r\n","<div class=\"hw\">pūbuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://pūbescō\">pubesco</a>.</div>\r\n","<div class=\"hw\">pūbēs<SUP>1</SUP>, pūber</div><div class=\"pos\">-eris, <i>adj</i></div><div class=\"def\"><num>①</num> 成長した, 成人した.</div><div class=\"def\"><num>②</num> (葉・果実が)みずみずしい.</div><hr><div class=\"hw\">pūbēs<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 陰毛;陰部.</div><div class=\"def\"><num>②</num> 思春期.</div><div class=\"def\"><num>③</num> 成年男子.</div><div class=\"def\"><num>④</num> 人々, 群衆.</div>\r\n","<div class=\"hw\">pūga, pȳga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">尻, 臀部(=<a href=\"entry://natis\">natis</a>).</div>\r\n","<div class=\"hw\">pūgiunculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↑<a href=\"entry://pūgiō\">pūgiō</a>]</div><div class=\"def\">(小さな)短剣.</div>\r\n","<div class=\"hw\">pūgiō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[pungo]</div><div class=\"def\">短刀, 短剣</div><div class=\"ex\"><i>plumbeus</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">鉛の短刀(=説得力のない議論).</span></div>\r\n","<div class=\"hw\">pūlex</div><div class=\"pos\">-licis, <i>m</i></div><div class=\"def\">〘昆〙</div><div class=\"def\"><num>①</num> ノミ(蚤).</div><div class=\"def\"><num>②</num> アリマキ.</div>\r\n","<div class=\"hw\">pūlicārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://pūlex\">pūlex</a>]</div><div class=\"def\">ノミの;ノミを発生させる.</div>\r\n","<div class=\"hw\">pūlicōsus</div><div class=\"pos\">-a -um, <i>adv</i></div><div class=\"ori\">[pulex]</div><div class=\"def\">ノミの多い, ノミがたかった.</div>\r\n","<div class=\"hw\">pūlēium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙ハッカ(薄荷)の類;清涼剤.</div>\r\n","<div class=\"hw\">pūmex</div><div class=\"pos\">-micis, <i>m</i>(<i>f</i>)</div><div class=\"def\"><num>①</num> 軽石</div><div class=\"ex\"><i>libellum pumice expolitum</i> (<author>C<small>ATUL</small></author>)<span class=\"ext\">端を軽石で磨いた小さな本.</span></div><div class=\"def\"><num>②</num> 多孔質の岩石.</div>\r\n","<div class=\"hw\">pūmiceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://pūmex\">pūmex</a>]</div><div class=\"def\">軽石の.</div>\r\n","<div class=\"hw\">pūmicō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[pumex]</div><div class=\"def\">(軽石でこすって)なめらかにする.</div>\r\n","<div class=\"hw\">pūmicōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pumex]</div><div class=\"def\">軽石のような;多孔質の.</div>\r\n","<div class=\"hw\">pūmiliō</div><div class=\"pos\">-ōnis, <i>m</i>(<i>f</i>)</div><div class=\"ori\">[↓<a href=\"entry://pūmilus\">pūmilus<SUP>1</SUP></a>]</div><div class=\"def\">小人<SUB>こびと</SUB>, 一寸法師.</div>\r\n","<div class=\"hw\">pūmilus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">矮小の.</div><hr><div class=\"hw\">pūmilus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://pūmiliō\">pumilio</a>.</div>\r\n","<div class=\"hw\">pūnicans</div><div class=\"pos\">-antis, <i>adj</i></div><div class=\"ori\">[puniceus]</div><div class=\"def\">赤くなる.</div>\r\n","<div class=\"hw\">pūniceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">緋色の, 深紅色の.</div>\r\n","<div class=\"hw\">Pūnicus, -ceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Carthago(人)の</div><div class=\"ex\"><i>Punica fides</i> (<author>L<small>IV</small></author>)<span class=\"ext\">背信, 不実.</span></div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>Punicum malum</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">〘植〙ザクロ</span></div><div class=\"ex\"><i>Punica malus</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">ザクロの木.</span></div><div class=\"def\"><num>③</num> =<a href=\"entry://pūniceus\">puniceus</a>.</div>\r\n","<div class=\"hw\">Pūnicānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[Punicus]</div><div class=\"def\">Carthago 風の.</div>\r\n","<div class=\"hw\">Pūnicē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[Punicus]</div><div class=\"def\">Carthago のことばで.</div>\r\n","<div class=\"hw\">pūnior</div><div class=\"pos\">-īrī -ītus sum, <i>tr dep</i></div><div class=\"def\">=<a href=\"entry://pūniō\">punio</a>.</div>\r\n","<div class=\"hw\">pūniō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>tr</i></div><div class=\"def\"><num>①</num> 罰する, 懲らしめる 〈alqm [alqd]〉.</div><div class=\"def\"><num>②</num> 復讐する.</div>\r\n","<div class=\"hw\">pūnītiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[punio]</div><div class=\"def\">処罰, 懲罰.</div>\r\n","<div class=\"hw\">pūnītor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[punio]</div><div class=\"def\"><num>①</num> 処罰する人.</div><div class=\"def\"><num>②</num> 復讐者.</div>\r\n","<div class=\"hw\">pūnītus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://pūniō\">punio</a>, <a href=\"entry://pūnior\">punior</a>.</div>\r\n","<div class=\"hw\">pūpa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[pupus]</div><div class=\"def\"><num>①</num> 少女, 女の子.</div><div class=\"def\"><num>②</num> 人形.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘昆〙サナギ(蛹).</div>\r\n","<div class=\"hw\">pūpilla</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[pupa]</div><div class=\"def\"><num>①</num> 後見人の保護下にある少女.</div><div class=\"def\"><num>②</num> 瞳孔, ひとみ.</div>\r\n","<div class=\"hw\">pūpillus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[pupulus]</div><div class=\"def\">後見人の保護下にある少年.</div>\r\n","<div class=\"hw\">pūpillāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[pupillus]</div><div class=\"def\">後見人の保護下にある未成年者の.</div>\r\n","<div class=\"hw\">pūpillātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://pūpillus\">pūpillus</a>]</div><div class=\"def\">《碑》被後見者の身分[年齢].</div>\r\n","<div class=\"hw\">Pūpinia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[Pupinius]</div><div class=\"def\">プーピニア《Latium の一地方;ローマと Tusculum の間の不毛地帯》.</div>\r\n","<div class=\"hw\">Pūpiniensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Pūpinius\">Pupinius</a>.</div>\r\n","<div class=\"hw\">Pūpinius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><i>ager ～</i> (<author>F<small>EST</small></author>) =<a href=\"entry://Pūpinia\">Pupinia</a>.</div>\r\n","<div class=\"hw\">Pūpius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">プーピウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">pūpula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[pupa]</div><div class=\"def\"><num>①</num> (小さな)少女.</div><div class=\"def\"><num>②</num> 瞳孔, ひとみ.</div>\r\n","<div class=\"hw\">pūpulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://pūpus\">pūpus</a>]</div><div class=\"def\"><num>①</num> (小さな)少年.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 人形.</div>\r\n","<div class=\"hw\">pūpus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 少年, 男の子.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 瞳孔, ひとみ.</div>\r\n","<div class=\"hw\">pūpārium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↑<a href=\"entry://pūpa\">pūpa</a>]</div><div class=\"def\">〘昆〙囲蛹<SUB>いよう</SUB>殻.</div>\r\n","<div class=\"hw\">pūrificātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[purifico]</div><div class=\"def\">(儀式によって)清めること.</div>\r\n","<div class=\"hw\">pūrificātōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://pūrificātōrius\">pūrificātōrius</a>]</div><div class=\"def\">〘教会〙聖杯(清め)布巾<SUB>ふきん</SUB>.</div>\r\n","<div class=\"hw\">pūrificātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://pūrificō\">pūrificō</a>]</div><div class=\"def\">清めの.</div>\r\n","<div class=\"hw\">pūrificō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[purus/facio]</div><div class=\"def\"><num>①</num> (不要物・よごれなどを)取り除く, きれいにする.</div><div class=\"def\"><num>②</num> (儀式によって)清める.</div>\r\n","<div class=\"hw\">pūrigō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">《古形》=<a href=\"entry://purgō\">purgo</a>.</div>\r\n","<div class=\"hw\">pūriter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[purus]</div><div class=\"def\"><num>①</num> 清潔に, きれいに.</div><div class=\"def\"><num>②</num> 清廉に.</div>\r\n","<div class=\"hw\">pūritās<SUP>1</SUP></div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[purus]</div><div class=\"def\"><num>①</num> 清潔, 清浄, 清澄.</div><div class=\"def\"><num>②</num> (文体の)純正, 正格.</div><hr><div class=\"hw\">pūritās<SUP>2</SUP></div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[pus]</div><div class=\"def\">〘病〙膿<SUB>うみ</SUB>, 化膿.</div>\r\n","<div class=\"hw\">pūrulentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://pūrulentus\">pūrulentus</a>]</div><div class=\"def\"><num>①</num> 膿<SUB>うみ</SUB>.</div><div class=\"def\"><num>②</num> (比喩的に)かす, くず.</div>\r\n","<div class=\"hw\">pūrulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pus]</div><div class=\"def\">膿<SUB>うみ</SUB>の, 膿んだ.</div>\r\n","<div class=\"hw\">pūrulentātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[purulentus]</div><div class=\"def\">化膿.</div>\r\n","<div class=\"hw\">pūrulentē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[purulentus]</div><div class=\"def\">膿状に.</div>\r\n","<div class=\"hw\">pūrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://pūrus\">pūrus</a>]</div><div class=\"def\">晴天, 青空.</div>\r\n","<div class=\"hw\">pūrus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 清潔な, きれいな, よごれていない.</div><div class=\"def\"><num>②</num> 純粋な, まじりけのない.</div><div class=\"def\"><num>③</num> (天体・空などが)澄みきった, 曇りのない.</div><div class=\"def\"><num>④</num> (宗教的に)けがれのない, 清い.</div><div class=\"def\"><num>⑤</num> (道徳的に)けがれのない, 清廉な;貞潔な, 純潔な.</div><div class=\"def\"><num>⑥</num> 障害物のない</div><div class=\"ex\"><i>～ ab arboris campus</i> (<author>O<small>V</small></author>)<span class=\"ext\">樹木のない野原.</span></div><div class=\"def\"><num>⑦</num> 装飾のない</div><div class=\"ex\"><i>toga pura</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(紫の縁飾りのない)白地のままのトガ《ローマ市民の平服;<i>cf. </i> toga praetexta》</span></div><div class=\"ex\"><i>hasta pura</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">(軍功の褒美の)穂先のない槍.</span></div><div class=\"def\"><num>⑧</num> (文体が)平明な, 飾らない.</div><div class=\"def\"><num>⑨</num> 〘法〙無条件の, 絶対的な.</div>\r\n","<div class=\"hw\">pūrē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[purus]</div><div class=\"def\"><num>①</num> 清潔に, きれいに.</div><div class=\"def\"><num>②</num> 清らかに, けがれなく.</div><div class=\"def\"><num>③</num> 明快に, 明瞭に.</div><div class=\"def\"><num>④</num> 〘法〙無条件で, 絶対的に.</div>\r\n","<div class=\"hw\">pūs</div><div class=\"pos\">pūris, <i>n</i></div><div class=\"def\"><num>①</num> 膿<SUB>うみ</SUB>.</div><div class=\"def\"><num>②</num> (悪口として)げす野郎.</div>\r\n","<div class=\"hw\">pūsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[pusus]</div><div class=\"def\">少女.</div>\r\n","<div class=\"hw\">pūsiō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[pusus]</div><div class=\"def\">少年, 男の子.</div>\r\n","<div class=\"hw\">pūsula, pussula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[pus]</div><div class=\"def\"><num>①</num> 〘病〙水ぶくれ, 吹き出物, 膿疱.</div><div class=\"def\"><num>②</num> 水泡, あぶく.</div>\r\n","<div class=\"hw\">pūsulātus, pustu-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://pūsula\">pūsula, pussula</a>]</div><div class=\"def\">精錬された.</div>\r\n","<div class=\"hw\">pūsulōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[pusula]</div><div class=\"def\">水ぶくれ[膿疱]のある.</div>\r\n","<div class=\"hw\">pūsus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">少年, 男の子.</div>\r\n","<div class=\"hw\">pūtescō, -iscō</div><div class=\"pos\">-ere pūtuī, <i>intr inch</i></div><div class=\"ori\">[puteo]</div><div class=\"def\">腐り始める, 悪臭を放ち始める.</div>\r\n","<div class=\"hw\">pūteō</div><div class=\"pos\">-ēre -tuī, <i>intr</i></div><div class=\"def\"><num>①</num> いやな匂いがする, 悪臭を放つ.</div><div class=\"def\"><num>②</num> 腐っている.</div>\r\n","<div class=\"hw\">pūtidiusculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://pūtidus\">pūtidus</a>]</div><div class=\"def\">いささかお世辞がすぎる.</div>\r\n","<div class=\"hw\">pūtidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[puteo]</div><div class=\"def\"><num>①</num> 腐った, 悪臭を放つ.</div><div class=\"def\"><num>②</num> 老いさらばえた, もうろくした.</div><div class=\"def\"><num>③</num> (人について)不快な, うんざりする;(語り口が)気取った.</div>\r\n","<div class=\"hw\">pūtidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[putidus]</div><div class=\"def\">気取って, 知ったかぶりをして.</div>\r\n","<div class=\"hw\">pūtiscō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\">=<a href=\"entry://pūtescō\">putesco</a>.</div>\r\n","<div class=\"hw\">pūtor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[puteo]</div><div class=\"def\">腐敗, 悪臭.</div>\r\n","<div class=\"hw\">pūtuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://pūteō\">puteo</a>, <a href=\"entry://pūtescō\">putesco</a>.</div>\r\n"]);
